import { Grid, TextField, Button, Box, Typography, IconButton, Card, CardContent, Divider } from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';

const PromptTemplatesCard = ({
    view,
    categories,
    filteredPrompts,
    searchTerm,
    formikValues,
    theme,
    handleCategoryClick,
    handleBackToCategories,
    handlePromptSelect,
    setSearchTerm
}) => {
    const getCategoryName = () => {
        if (!view || view === 'categories') return '';
        const selectedId = view.split('-')[1];
        const category = categories.find((cat) => cat.id === parseInt(selectedId, 10));
        return category ? category.name : '';
    };

    // Filter categories based on search term
    const filteredCategories = categories?.filter((category) => category.name.toLowerCase().includes(searchTerm.toLowerCase())) || [];

    return (
        <Card
            sx={{
                height: '100vh',
                display: 'flex',
                flexDirection: 'column',
                background: 'white',
                border: '2px solid gray',
                boxShadow: '3'
            }}
        >
            <CardContent>
                {/* Header with title and back button */}
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                    {view !== 'categories' && (
                        <IconButton onClick={handleBackToCategories} sx={{ mr: 1 }}>
                            <ArrowBackIcon />
                        </IconButton>
                    )}
                    <Typography variant="h6" sx={{ flexGrow: 1 }}>
                        {view === 'categories' ? 'Prompt Templates' : getCategoryName()}
                    </Typography>
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Content Area */}
                <Box
                    sx={{
                        overflowY: 'auto',
                        height: '65vh',
                        pr: 1,
                        '&::-webkit-scrollbar': { width: '6px' },
                        '&::-webkit-scrollbar-thumb': { bgcolor: 'divider' }
                    }}
                >
                    {/* Unified search field with dynamic placeholder */}
                    <TextField
                        size="medium"
                        placeholder={view === 'categories' ? 'Search categories...' : 'Search prompts...'}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        InputProps={{
                            startAdornment: <SearchIcon fontSize="small" sx={{ mr: 1 }} />
                        }}
                        sx={{ width: '100%', border: '0.5px solid gray', borderRadius: '10px' }}
                    />

                    {view === 'categories' ? (
                        <>
                            <Typography variant="subtitle1" sx={{ mb: 1, mt: 2 }}>
                                Categories
                            </Typography>

                            {filteredCategories.length > 0 ? (
                                <Grid container spacing={1} sx={{ mb: 2 }}>
                                    {filteredCategories.map((category) => (
                                        <Grid item xs={4} key={category.id}>
                                            <Box
                                                onClick={() => handleCategoryClick(category.id)}
                                                sx={{
                                                    p: 1.5,
                                                    border: '2px solid gray',
                                                    borderRadius: 1,
                                                    borderColor: 'divider',
                                                    textAlign: 'center',
                                                    cursor: 'pointer',
                                                    bgcolor: 'white',
                                                    '&:hover': {
                                                        bgcolor: 'action.hover'
                                                    }
                                                }}
                                            >
                                                <Typography variant="h1" sx={{ mb: 0.5 }}>
                                                    <i className="fas fa-box" />
                                                </Typography>
                                                <Typography variant="body3" color="text.dark">
                                                    {category.name}
                                                </Typography>
                                            </Box>
                                        </Grid>
                                    ))}
                                </Grid>
                            ) : (
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                                    No categories found {searchTerm ? `for "${searchTerm}"` : ''}
                                </Typography>
                            )}
                        </>
                    ) : (
                        <>
                            <Typography variant="subtitle1" sx={{ mb: 1, mt: 3 }}>
                                Prompts
                            </Typography>
                            <Box>
                                {filteredPrompts?.length > 0 ? (
                                    filteredPrompts.map((prompt) => (
                                        <Card
                                            key={prompt.id}
                                            onClick={() => handlePromptSelect(prompt.prompt)}
                                            sx={{
                                                mb: 1,
                                                cursor: 'pointer',
                                                border: 1,
                                                borderColor: 'divider',
                                                background: 'white',
                                                '&:hover': {
                                                    borderColor: 'primary.main'
                                                }
                                            }}
                                        >
                                            <CardContent
                                                sx={{
                                                    py: 1.5,
                                                    '&:last-child': { pb: 1.5 }
                                                }}
                                            >
                                                <Typography variant="subtitle2">Title::{prompt.title}</Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Text::{prompt.prompt}
                                                </Typography>
                                            </CardContent>
                                        </Card>
                                    ))
                                ) : (
                                    <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                                        No prompts found {searchTerm ? `for "${searchTerm}"` : 'in this category'}
                                    </Typography>
                                )}
                            </Box>
                        </>
                    )}
                </Box>
            </CardContent>
        </Card>
    );
};

export default PromptTemplatesCard;
