/* eslint-disable prettier/prettier */
import React, { useState, useEffect } from 'react';
import { Grid, useTheme, CircularProgress, Box } from '@mui/material';
import { useFormik } from 'formik';
import * as yup from 'yup';
import PromptFormCard from './PromptFormCard';
import PromptTemplatesCard from './PromptTemplatesCard';
import GeneratedTextCard from './GeneratedTextCard';
import { useDispatch } from 'store';
import { openSnackbar } from 'store/slices/snackbar';
import ApiRequest from 'utils/apiService';

const validationSchema = yup.object({
    promptText: yup.string().required('Prompt is required'),
    language: yup.string().required('Language is required'),
    words: yup.number().min(10).max(1000).required('Word count is required'),
    tone: yup.string().required('Tone is required'),
    creativity: yup.string().required('Creativity level is required'),
    hashtags: yup.boolean(),
    resultNumber: yup.number().min(1).max(5).required('Result number is required')
});

const AiPrompt = () => {
    const theme = useTheme();
    const [view, setView] = useState('categories'); // Just JavaScript, no types
    const [searchTerm, setSearchTerm] = useState('');
    const [categories, setCategories] = useState([]);
    const [filteredPrompts, setFilteredPrompts] = useState([]);
    const [generatedText, setGeneratedText] = useState('');
    const [loading, setLoading] = useState(false);
    const [dataLoading, setDataLoading] = useState(true); // For initial data load
    const dispatch = useDispatch();

    // Fetch categories and prompts from API
    useEffect(() => {
        const fetchData = async () => {
            try {
                setDataLoading(true);
                const response = await ApiRequest('GET', 'content-generator/categories');
                setCategories(response.data);
                // Flatten all prompts for search functionality
                const allPrompts = response.data.flatMap((category) =>
                    category.prompts.map((prompt) => ({ ...prompt, categoryId: category.id }))
                );
                setFilteredPrompts(allPrompts);
            } catch (error) {
                dispatch(
                    openSnackbar({
                        open: true,
                        message: 'Failed to load categories and prompts',
                        variant: 'alert',
                        alert: { color: 'error' },
                        close: false
                    })
                );
            } finally {
                setDataLoading(false);
            }
        };

        fetchData();
    }, [dispatch]);

    // Filter prompts based on category and search term
    // Update the filtering logic in the second useEffect
    useEffect(() => {
        if (dataLoading) return;

        let result = [];

        if (view === 'categories') {
            // Show all prompts when searching in categories view
            result = categories.flatMap((category) =>
                category.prompts.map((prompt) => ({
                    ...prompt,
                    categoryId: category.id,
                    categoryName: category.name // Add category name for reference
                }))
            );
        } else {
            // Filter by category
            const categoryId = parseInt(view.split('-')[1], 10);
            const category = categories.find((cat) => cat.id === categoryId);
            result = category
                ? category.prompts.map((p) => ({
                    ...p,
                    categoryId: category.id,
                    categoryName: category.name
                }))
                : [];
        }

        // Apply search filter
        if (searchTerm) {
            const term = searchTerm.toLowerCase();
            result = result.filter((prompt) => prompt.title.toLowerCase().includes(term) || prompt.prompt.toLowerCase().includes(term));
        }

        setFilteredPrompts(result);
    }, [view, searchTerm, categories, dataLoading]);
    const formik = useFormik({
        initialValues: {
            promptText: '',
            language: 'English',
            words: 50,
            tone: 'Neutral',
            creativity: 'Medium',
            hashtags: false,
            resultNumber: 1
        },
        validationSchema,
        onSubmit: async (values) => {
            setLoading(true);
            try {
                const response = await ApiRequest('POST', 'deep-seek/generate-content', values);

                if (!response?.data) {
                    throw new Error(response?.message || 'Failed to generate content');
                }

                dispatch(
                    openSnackbar({
                        open: true,
                        message: 'Response received successfully',
                        variant: 'alert',
                        alert: { color: 'success' },
                        close: false
                    })
                );

                setGeneratedText(response.data);
            } catch (error) {
                dispatch(
                    openSnackbar({
                        open: true,
                        message: error.message || 'Failed to generate content',
                        variant: 'alert',
                        alert: { color: 'error' },
                        close: false
                    })
                );
            } finally {
                setLoading(false);
            }
        }
    });

    const handleCategoryClick = (categoryId) => {
        setView(`category-${categoryId}`);
        setSearchTerm('');
    };

    const handleBackToCategories = () => {
        setView('categories');
        setSearchTerm('');
    };

    const handlePromptSelect = (promptText) => {
        formik.setFieldValue('promptText', promptText);
    };

    const handleCopyToClipboard = () => {
        navigator.clipboard.writeText(generatedText);
        dispatch(
            openSnackbar({
                open: true,
                message: 'Copied to clipboard',
                variant: 'alert',
                alert: { color: 'success' },
                close: false
            })
        );
    };

    if (dataLoading) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" height="100vh">
                <CircularProgress />
            </Box>
        );
    }

    return (
        <Grid container spacing={1} sx={{ p: 3 }}>
            {/* Left Column: Prompt Templates */}
            <Grid item xs={12} md={4}>
                <PromptTemplatesCard
                    view={view}
                    categories={categories}
                    filteredPrompts={filteredPrompts}
                    searchTerm={searchTerm}
                    formikValues={formik.values}
                    theme={theme}
                    handleCategoryClick={handleCategoryClick}
                    handleBackToCategories={handleBackToCategories}
                    handlePromptSelect={handlePromptSelect}
                    setSearchTerm={setSearchTerm}
                />
            </Grid>

            {/* Middle Column: Prompt Form */}
            <Grid item xs={12} md={4}>
                <PromptFormCard formik={formik} loading={loading} />
            </Grid>

            {/* Right Column: Generated Text */}
            <Grid item xs={12} md={4}>
                {loading ? (
                    <Box display="flex" justifyContent="center" alignItems="center" height="100%">
                        <CircularProgress />
                    </Box>
                ) : (
                    <GeneratedTextCard generatedText={generatedText} handleCopyToClipboard={handleCopyToClipboard} />
                )}
            </Grid>
        </Grid>
    );
};

export default AiPrompt;
