import { Box, Typography, IconButton, Card, CardContent, Divider } from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';

const GeneratedTextCard = ({ generatedText, handleCopyToClipboard }) => (
    <Card sx={{ height: '100vh', display: 'flex', flexDirection: 'column' }}>
        <CardContent
            sx={{
                flexGrow: 1,
                background: 'white',
                border: '2px solid gray',
                boxShadow: '3'
            }}
        >
            <Box
                sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    mb: 1,
                    overflowY: 'auto'
                }}
            >
                <Typography variant="h6">Generated Text</Typography>
                <IconButton onClick={handleCopyToClipboard} disabled={!generatedText} color="primary">
                    <ContentCopyIcon />
                </IconButton>
            </Box>

            <Divider sx={{ my: 1 }} />

            <Box
                sx={{
                    whiteSpace: 'pre-wrap',
                    fontSize: '0.875rem',
                    height: '100%',
                    overflowY: 'auto',
                    p: 1,
                    bgcolor: 'action.hover',
                    borderRadius: 1,
                    minHeight: '300px'
                }}
            >
                {generatedText ? (
                    <Typography color="text.dark">{generatedText}</Typography>
                ) : (
                    <Typography color="text.dark">Generated content will appear here</Typography>
                )}
            </Box>
        </CardContent>
    </Card>
);

export default GeneratedTextCard;
